n.jsLib:
function host(){
  var src=this.source;
  var m=src?src.getLoginInfoMap():null;
  var h=(m&&m["线路"])||"https://www.pili45.com";
  if(String(h).indexOf("http")!=0){
    if(String(h).indexOf("pilibook")>=0) h="https://www.pilibook.net";
    else if(String(h).indexOf("pilishuwu")>=0) h="https://www.pilishuwu.com";
    else h="https://www.pili45.com";
  }
  return String(h).replace(/\/$/,"");
}

